import dataclasses
import typing


@dataclasses.dataclass
class TranscriptionConfig:
    audio_uri: str
    language_code: str
    diarization_enabled: bool = False
    word_level_timestamps_enabled: bool = False
    display_name: str = "transcription_job"


@dataclasses.dataclass
class TranscriptionResult:
    job_id: str
    status: str
    transcript: typing.Optional[str] = None
    word_timestamps: typing.Optional[typing.List[typing.Dict]] = None
    speaker_segments: typing.Optional[typing.List[typing.Dict]] = None


@dataclasses.dataclass
class TranslatedSegment:
    segment_id: int
    text: str
    translated_text: str
    source_language: str
    target_language: str


@dataclasses.dataclass
class ModerationResult:
    segment_id: int
    text: str
    flagged: bool
    categories: typing.List[str]


@dataclasses.dataclass
class SummaryResult:
    summary: str


@dataclasses.dataclass
class EmbeddingResult:
    segment_id: int
    text: str
    embedding: typing.List[float]

import os
import requests
from speech_models import TranscriptionConfig


class AzureSpeechClient:
    def __init__(self, region: str = None, api_key: str = None):
        self.region = region or os.environ.get('AZURE_SPEECH_REGION')
        self.api_key = api_key or os.environ.get('AZURE_SPEECH_KEY')

        if not self.region or not self.api_key:
            raise ValueError("Azure Speech region and API key must be provided or set in environment variables.")

        self.base_url = f"https://{self.region}.api.cognitive.microsoft.com/speechtotext/v3.1"

    def submit_transcription_job(self, config: TranscriptionConfig):
        headers = {
            'Ocp-Apim-Subscription-Key': self.api_key,
            'Content-Type': 'application/json'
        }
        payload = {
            'contentUrls': [config.audio_uri],
            'locale': config.language_code,
            'displayName': config.display_name,
            'properties': {
                'diarizationEnabled': config.diarization_enabled,
                'wordLevelTimestampsEnabled': config.word_level_timestamps_enabled,
                'languageIdentification': {
                    'candidateLocales': [config.language_code]
                }
            }
        }
        response = requests.post(
            f"{self.base_url}/transcriptions",
            headers=headers,
            json=payload,
            timeout=30
        )
        response.raise_for_status()
        return response.json()

    def get_transcription_job(self, job_id: str):
        headers = {
            'Ocp-Apim-Subscription-Key': self.api_key
        }
        response = requests.get(
            f"{self.base_url}/transcriptions/{job_id}",
            headers=headers,
            timeout=30
        )
        response.raise_for_status()
        return response.json()

    def get_transcription_result(self, result_url: str):
        headers = {
            'Ocp-Apim-Subscription-Key': self.api_key
        }
        response = requests.get(
            result_url,
            headers=headers,
            timeout=30
        )
        response.raise_for_status()
        return response.json()

import time
from speech_client import AzureSpeechClient
from speech_models import TranscriptionResult

def poll_transcription(job_id: str, client: AzureSpeechClient, timeout_seconds: int = 600) -> TranscriptionResult:
    start_time = time.time()
    while time.time() - start_time < timeout_seconds:
        job_details = client.get_transcription_job(job_id)
        status = job_details['status']

        if status == 'Succeeded':
            # Azure Speech-to-Text provides a 'files' URL for the results
            files_url = job_details['links']['files']
            files_response = client.get_transcription_result(files_url)

            # Find the file that contains the actual transcript (typically a JSON file)
            transcript_file_url = None
            for file_item in files_response['values']:
                if file_item['kind'] == 'Transcription' and file_item['properties']['dataType'] == 'Result':
                    transcript_file_url = file_item['links']['contentUrl']
                    break

            if transcript_file_url:
                transcript_content = client.get_transcription_result(transcript_file_url)
                full_transcript = " ".join([phrase['display'] for segment in transcript_content['recognizedPhrases'] for phrase in [segment]])
                return TranscriptionResult(job_id=job_id, status=status, transcript=full_transcript)
            else:
                return TranscriptionResult(job_id=job_id, status=status, transcript=None) # Should not happen for successful jobs
        elif status in ['Failed', 'Cancelled']:
            return TranscriptionResult(job_id=job_id, status=status)

        time.sleep(5)  # Wait for 5 seconds before polling again

    return TranscriptionResult(job_id=job_id, status="Timeout", transcript=None)
